import { useMemo } from 'react';

import { Table } from 'components';
import { TableDataType } from 'components/Table/types';
import { useGlobalDataAvailability } from 'contexts';

import { tableConfig } from './config';
import { StyledPortfolioPerformanceTableContainer } from './PortfolioPerformanceTable.styles';

interface PortfolioPerformanceTableProps {
  data: TableDataType;
  headerHeight?: number;
  dataTestId?: string;
  rowHeight?: number;
  isGlobalView?: boolean;
}

export const PortfolioPerformanceTable = ({
  data,
  headerHeight,
  dataTestId,
  rowHeight = 94,
  isGlobalView,
}: PortfolioPerformanceTableProps) => {
  const { shouldShowGlobalBanner } = useGlobalDataAvailability();
  const shouldHidePowerData =
    shouldShowGlobalBanner('power') && (isGlobalView ?? true);

  const processedData = useMemo((): TableDataType => {
    if (!shouldHidePowerData) return data;
    return {
      ...data,
      rows: data.rows.map((group) =>
        group.map((row) => {
          if ('isEmpty' in row && row.isEmpty) return row;
          const typedRow = row as Record<string, unknown>;
          return {
            ...typedRow,
            brand_power_vs_ly: { value: '-' },
            brand_power_vs_ly_config: undefined,
          };
        }),
      ),
    };
  }, [data, shouldHidePowerData]);

  return (
    <Table
      data={processedData}
      columnDefsConfig={tableConfig}
      style={StyledPortfolioPerformanceTableContainer}
      rowHeight={rowHeight}
      headerHeight={headerHeight}
      scrollbarWidth={0}
      emptyRow={{
        addOnStart: true,
      }}
      {...({ dataTestId } as Record<string, unknown>)}
    />
  );
};
